  // 3. Sold-out restock waitlist: customer:waitlist:<productId>
  bot.callbackQuery(/^customer:waitlist:(.+)$/, async (ctx) => {
    await ctx.answerCallbackQuery();
    const rawProductId = ctx.match[1];
    const isNumeric = /^\d+$/.test(rawProductId);
    const productId = isNumeric ? Number(rawProductId) : rawProductId;
    const customer = ctx.from;
    if (!customer) return;

    try {
      let pName = "Product";
      if (isNumeric) {
        const product = await CatalogService.getProductById(Number(productId));
        if (product?.name) pName = product.name;
      }

      if (isCloudFirestore()) {
        await FirestoreStore.createWaitlistEntry({
          customerId: customer.id,
          customerUsername: customer.username || null,
          productId: isNumeric ? Number(productId) : 0,
          productName: pName,
        });
      }

      await ctx.reply(
        `🔔 <b>Added to Restock Waitlist!</b>\n\n` +
          `You have joined the waitlist for <b>${escapeHtml(pName)}</b>.\n` +
          `We will notify you immediately once this item is restocked and available for order!`,
        {
          parse_mode: "HTML",
          reply_markup: new InlineKeyboard()
            .text("🛒 Browse Other Products", "customer:catalog:categories")
            .row()
            .text("🔙 Main Menu", "customer:menu:main"),
        }
      );
    } catch (err: any) {
      log.error({ err: err.message }, "Error adding to waitlist");
      await ctx.reply("❌ Could not add to waitlist at this time.");
    }
  });
}

